import{_ as o,o as t,c as a,a7 as l}from"./chunks/framework.CZ-joWLZ.js";const f=JSON.parse('{"title":"Installing/updating manually","description":"Installing Axolotl-PM manually.","frontmatter":{"title":"Installing/updating manually","outline":"deep","description":"Installing Axolotl-PM manually.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/installation/installing-manually"}]]},"headers":[],"relativePath":"docs/installation/installing-manually.md","filePath":"docs/installation/installing-manually.md","lastUpdated":1790689997000}'),r={name:"docs/installation/installing-manually.md"};function n(i,e,s,d,c,u){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="installing-updating-manually" tabindex="-1">Installing/updating manually <a class="header-anchor" href="#installing-updating-manually" aria-label="Permalink to &quot;Installing/updating manually&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Installing manually is complicated. Don’t attempt it unless you have no other option.</p></div><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><ol><li>Make a folder for your server. If you’re updating an existing server, delete <code>PocketMine-MP.phar</code>, any file called <code>start</code>, and the <code>bin</code> folder from the folder.</li><li>Download the custom PHP binary for Windows <a href="https://github.com/axolotl-pm/PHP-Binaries/releases" target="_blank" rel="noreferrer">here</a>. <strong>Make sure you get the right version for your chosen version of Axolotl-PM</strong> (see below).</li><li>Right-click -&gt; click Extract All, pick your server folder and click Extract. Now you should have a folder called <code>bin</code>.</li><li>In the <code>bin</code> folder, double-click the file <code>vc_redist.x64.exe</code>, accept the terms and conditions, and install. This will install Microsoft Visual C++ Redistributable, which is needed by the PHP binary.</li><li>Download your chosen version of <code>PocketMine-MP.phar</code> and <code>start.cmd</code> from <a href="https://github.com/axolotl-pm/PocketMine-MP/releases" target="_blank" rel="noreferrer">here</a> and save them in your server folder.</li></ol><p>Now you should be able to double-click <code>start.cmd</code> to start the server.</p><h2 id="linux-macos" tabindex="-1">Linux/MacOS <a class="header-anchor" href="#linux-macos" aria-label="Permalink to &quot;Linux/MacOS&quot;">​</a></h2><p>The following steps require you to use the Terminal.</p><ol><li><code>cd</code> to wherever you want to put the server (e.g. <code>cd /home/dylan</code>).</li><li>Make a folder for your server using <code>mkdir</code> (e.g. <code>mkdir pocketmine</code>). If you’re updating an existing server, <code>cd</code> directly to your server’s folder instead.</li><li>Run <code>rm -rf ./bin ./PocketMine-MP.phar ./start.sh</code>. This deletes any outdated server files (don’t worry, your data won’t be harmed).</li><li>Find the download link for the right PHP version for your OS. You can see a list of available ones <a href="https://github.com/axolotl-pm/PHP-Binaries/releases" target="_blank" rel="noreferrer">here</a>.</li><li>Run <code>curl -L &lt;link to your chosen PHP binary&gt; | tar -xz</code>. Now you should have a folder called <code>bin</code>. <strong>Make sure you get the right version for your chosen version of Axolotl-PM</strong> (see below).</li><li>Find the download link for your chosen version of <code>PocketMine-MP.phar</code> and <code>start.sh</code> <a href="https://github.com/axolotl-pm/PocketMine-MP/releases" target="_blank" rel="noreferrer">here</a>.</li><li>Run <code>curl -LO &lt;link to PocketMine-MP.phar&gt;</code>.</li><li>Run <code>curl -LO &lt;link to start.sh&gt;</code>.</li><li>Run <code>chmod +x ./start.sh</code>.`</li></ol><p>Now you should be able to run the server by running <code>./start.sh</code>.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Make sure you know which binary to use for your chosen version of Axolotl-PM. Different versions need different binaries. You can get some information about this from the <a href="https://update.axolotl-pm.org" target="_blank" rel="noreferrer">update.axolotl-pm.org API</a>.</p><p>Binaries have a suffix that tells you which Axolotl-PM version they are for. <code>PM4</code> is for 4.x, and <code>PM5</code> is for 5.x.</p><p>There are also different downloads for different operating systems, different CPU architectures and different versions of PHP itself.</p><p><strong>If you use the wrong binary, the server might not work.</strong></p></div>',10)])])}const p=o(r,[["render",n]]);export{f as __pageData,p as default};
